<template><div class="drawer-layer" @click.self="$emit('close')"><aside class="detail-drawer supply-detail"><div class="drawer-head"><div><span class="modal-kicker">SUPPLY RADAR · MOCK EVENT</span><h2>活动详情</h2></div><button class="icon-btn" @click="$emit('close')">×</button></div><div class="drawer-body"><div class="evidence-note"><span>●</span> 演示数据 · {{ event.verificationStatus }}</div><div class="supply-detail-title"><span :class="['event-type', event.standardCategory.indexOf('FAIR') > -1 ? 'fair' : 'talk']">{{ categoryLabels[event.standardCategory] }}</span><h3>{{ event.eventTitle }}</h3><p>{{ event.schoolName }} · {{ event.schoolCity }}</p></div><div class="detail-block"><label>基本信息</label><div class="detail-grid"><span>活动日期<strong>{{ event.eventDate }}</strong></span><span>时间<strong>{{ event.startTime }}{{ event.endTime ? '—' + event.endTime : '' }}</strong></span><span>举办形式<strong>{{ event.venueType }}</strong></span><span>地点<strong>{{ event.venueName || '暂无公开信息' }}</strong></span></div></div><div class="detail-block"><label>报名信息</label><p>报名截止：{{ event.registrationDeadline || '暂无公开信息' }}</p><p>相关企业：{{ event.companyNames.join('、') }}</p></div><div class="detail-block"><label>来源信息</label><p>来源高校：{{ event.schoolName }}</p><p>原始栏目：高校就业信息网（模拟）</p><p>最近采集：{{ event.updatedAt }}</p><a class="source-link" @click="$emit('source', event)">打开来源链接 ↗</a></div><div class="detail-block"><label>活动说明</label><p>{{ event.eventDescription }}</p><p class="change-note">{{ event.changeNote }}</p></div></div><div class="drawer-foot"><button class="ghost-btn" @click="$emit('close')">关闭</button><button class="primary-btn" @click="$emit('source', event)">打开来源</button></div></aside></div></template>
<script>
import { categoryLabels } from './mockSupplyRadar'
export default { name: 'SupplyDetailDrawer', props: { event: Object }, data () { return { categoryLabels: categoryLabels } } }
</script>



